/**
 * Benchmark orchestration for pre-generated agent trajectories.
 *
 * The runner is deliberately data-oriented: it loads trajectories already
 * generated by some agent harness, asks our verifier to select the best
 * candidate per task, and reports Pass@1, verifier selection accuracy, and
 * the oracle ceiling. This is the same evaluation shape used by the
 * LLM-as-a-Verifier reproduction studies, implemented independently on top
 * of this repository's TypeScript/Rust stack.
 */

import { selectTrajectories, type VerifierOptions } from './verifier.js'
import { loadTerminalBenchmark, type TerminalTrial } from './terminal-loader.js'
import { tokenUsage, type TokenUsageSnapshot } from './usage.js'
import type { BackendSettings, VerifierBackend } from './backend.js'
import type { CriteriaArgument } from './criteria.js'

export interface BenchmarkPreset {
  name: string
  trials: number
  pivots: number
  evaluations: number
}

export const BENCHMARK_PRESETS = {
  bo3: { name: 'bo3', trials: 3, pivots: 1, evaluations: 2 },
  bo5: { name: 'bo5', trials: 5, pivots: 2, evaluations: 2 },
  terminal_v2: { name: 'terminal_v2', trials: 5, pivots: 2, evaluations: 4 },
} as const satisfies Record<string, BenchmarkPreset>

export type BenchmarkPresetName = keyof typeof BENCHMARK_PRESETS

export interface BenchmarkEstimate {
  preset: BenchmarkPreset
  tasks: number
  comparisons: number
  verifierCalls: number
  criteriaCount: number
}

export interface TaskOutcome {
  taskName: string
  trials: Array<{ trialName: string; reward: number }>
  selectedIndex: number
  selectedReward: number
  firstReward: number
  oracleReward: number
  scores: number[]
  ranking: number[]
  nComparisons: number
}

export interface BenchmarkSummary {
  preset: BenchmarkPreset
  tasks: number
  passAt1: number
  verifierAccuracy: number
  oracleRate: number
  verifierUplift: number
  oracleGap: number
  nComparisons: number
  verifierCalls: number
  usage: TokenUsageSnapshot
}

export interface BenchmarkRun {
  createdAt: string
  agentDir: string
  limit?: number
  preset: BenchmarkPreset
  seed: number
  summary: BenchmarkSummary
  tasks: TaskOutcome[]
}

/** Number of directed comparisons for n candidates and k pivots. */
export function comparisonsFor(n: number, pivots: number): number {
  const k = Math.max(0, Math.min(pivots, n))
  if (n <= 1) return 0
  return n + k * (n - k) + (k * (k - 1)) / 2
}

/** Planned API-call volume for a full run with the given criteria count. */
export function estimateBenchmark(
  tasks: Map<string, TerminalTrial[]>,
  preset: BenchmarkPreset,
  criteriaCount: number,
): BenchmarkEstimate {
  let comparisons = 0
  let activeTasks = 0
  for (const trials of tasks.values()) {
    const n = Math.min(preset.trials, trials.length)
    if (n === 0) continue
    activeTasks += 1
    comparisons += comparisonsFor(n, preset.pivots)
  }
  return {
    preset,
    tasks: activeTasks,
    comparisons,
    verifierCalls: comparisons * preset.evaluations * criteriaCount,
    criteriaCount,
  }
}

function usageDelta(after: TokenUsageSnapshot, before: TokenUsageSnapshot): TokenUsageSnapshot {
  return {
    calls: after.calls - before.calls,
    inputTokens: after.inputTokens - before.inputTokens,
    cachedInputTokens: after.cachedInputTokens - before.cachedInputTokens,
    outputTokens: after.outputTokens - before.outputTokens,
    reasoningTokens: after.reasoningTokens - before.reasoningTokens,
  }
}

function mean(values: number[]): number {
  if (values.length === 0) return 0
  return values.reduce((sum, value) => sum + value, 0) / values.length
}

export interface RunTerminalBenchmarkInput {
  agentDir: string
  preset: BenchmarkPreset
  criteria: CriteriaArgument
  seed?: number
  limit?: number
  cache?: string | false
  settings?: BackendSettings
  overrides?: Partial<BackendSettings>
  cwd?: string
  backendInstance?: VerifierBackend
  onProgress?: (done: number, total: number, taskName: string) => void
}

/** Run a best-of-N verifier tournament over every task in an agent directory. */
export async function runTerminalBenchmark(
  input: RunTerminalBenchmarkInput,
): Promise<BenchmarkRun> {
  const tasks = await loadTerminalBenchmark(input.agentDir, input.preset.trials)
  const ordered = [...tasks.entries()]
  const selected = input.limit !== undefined && input.limit > 0 ? ordered.slice(0, input.limit) : ordered
  const usageBefore = tokenUsage.snapshot()
  const outcomes: TaskOutcome[] = []

  const options: VerifierOptions = {
    settings: input.settings,
    overrides: input.overrides,
    cwd: input.cwd,
    cache: input.cache,
    backendInstance: input.backendInstance,
  }

  let done = 0
  for (const [taskName, trials] of selected) {
    const candidates = trials.map((trial) => trial.trace)
    const problem = trials[0]?.problem ?? `(Task: ${taskName})`
    const result = await selectTrajectories(
      problem,
      candidates,
      input.criteria,
      input.preset.evaluations,
      input.preset.pivots,
      input.seed ?? 0,
      options,
    )
    const selectedTrial = trials[result.index] ?? trials[0]
    outcomes.push({
      taskName,
      trials: trials.map((trial) => ({ trialName: trial.trialName, reward: trial.reward })),
      selectedIndex: result.index,
      selectedReward: selectedTrial?.reward ?? 0,
      firstReward: trials[0]?.reward ?? 0,
      oracleReward: Math.max(...trials.map((trial) => trial.reward)),
      scores: result.scores,
      ranking: result.ranking,
      nComparisons: result.nComparisons,
    })
    done += 1
    input.onProgress?.(done, selected.length, taskName)
  }

  const passAt1 = mean(outcomes.map((outcome) => outcome.firstReward))
  const verifierAccuracy = mean(outcomes.map((outcome) => outcome.selectedReward))
  const oracleRate = mean(outcomes.map((outcome) => outcome.oracleReward))
  const summary: BenchmarkSummary = {
    preset: input.preset,
    tasks: outcomes.length,
    passAt1,
    verifierAccuracy,
    oracleRate,
    verifierUplift: verifierAccuracy - passAt1,
    oracleGap: oracleRate - verifierAccuracy,
    nComparisons: outcomes.reduce((sum, outcome) => sum + outcome.nComparisons, 0),
    verifierCalls: tokenUsage.snapshot().calls - usageBefore.calls,
    usage: usageDelta(tokenUsage.snapshot(), usageBefore),
  }

  return {
    createdAt: new Date().toISOString(),
    agentDir: input.agentDir,
    limit: input.limit,
    preset: input.preset,
    seed: input.seed ?? 0,
    summary,
    tasks: outcomes,
  }
}
